import{_ as u,a0 as a,w as r,s,I as i,x as t,a1 as l,A as o,ao as p}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const f=JSON.parse('{"title":"Canonical Dev称Linux Mint“脆弱”，不要将其用于网银 | LCTT x X-CMD","titleTemplate":false,"description":"Canonical Dev称Linux Mint“脆弱”，不要将其用于网银 | LCTT (201311) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Canonical Dev称Linux Mint“脆弱”，不要将其用于网银 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Canonical Dev称Linux Mint“脆弱”，不要将其用于网银 | LCTT (201311) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201311/Canonical Dev Calls Linux Mint ‘Vulnerable’, Wouldn’t Use it For Online Banking","title":"Canonical Dev称Linux Mint“脆弱”，不要将其用于网银","tag":"201311","desc":""},"relativePath":"201311/Canonical Dev Calls Linux Mint ‘Vulnerable’, Wouldn’t Use it For Online Banking.md","filePath":"[post].md"}'),d={name:"201311/Canonical Dev Calls Linux Mint ‘Vulnerable’, Wouldn’t Use it For Online Banking.md"};function x(m,n,C,b,M,v){const e=a("Link");return r(),s("div",null,[n[14]||(n[14]=i("h1",{id:"canonical-dev称linux-mint-脆弱-不要将其用于网银",tabindex:"-1"},[t("Canonical Dev称Linux Mint“脆弱”，不要将其用于网银 "),i("a",{class:"header-anchor",href:"#canonical-dev称linux-mint-脆弱-不要将其用于网银","aria-label":"Permalink to “Canonical Dev称Linux Mint“脆弱”，不要将其用于网银”"},"​")],-1)),i("p",null,[i("strong",null,[n[1]||(n[1]=t("一位Canonical公司",-1)),l(e,{href:"https://lists.ubuntu.com/archives/ubuntu-devel-discuss/2013-November/014770.html"},{default:o(()=>[...n[0]||(n[0]=[t("工程师建议",-1)])]),_:1}),n[2]||(n[2]=t("：基于Ubuntu的流行操作系统Linux Mint用户不应该将其用于网银 。",-1))])]),n[15]||(n[15]=p("<p>Mint决定禁止更新那些存在已知安全问题的安装包 - 从内核、浏览器到启动加载器和Xorg显示服务 - 这样给用户带来了一个“脆弱的系统” ，Oliver Grawert说。</p><blockquote><p>“不去马上整合Ubuntu提交的那些修正，而是拒绝这些软件包的（安全）更新。我要说，强制保持一个有缺陷的内核、浏览器或xorg，而不是允许安装更新补丁，这会变成一个易受攻击的系统，（原文如此）”。</p><p>“就我个人而言，我不会用它做网银操作。”</p></blockquote><p>当然不只有Grawert认为Mint在安全意识上的低下。Mozilla贡献者兼前Ubuntu成员 <strong>Benjamin Kerensa</strong> 也有同样的看法：</p><blockquote><p>“目前还不清楚为什么Linux Mint禁止所有的安全更新。我可以说，Mint需要花好几个月才能得到一个Firefox的修正版，而Ubuntu和Debian已经早在他们的包上打了安全补丁。</p><p>这将置Linux Mint用户处于危险中，也是我从来不建议任何人将Linux Mint作为一种替代Ubuntu的系统的主要原因之一。”</p></blockquote><p>Oliver Grawert是一位可靠的撰稿人。作为一位Canonical公司下的Ubuntu工程师，他比大多数人更了解自己在说什么。</p><p>那么Mint的用户存在实际风险么？</p><p>半对半错。Mint开发商坚决拒绝更新的现有软件包中大部分的安全“漏洞”（这个词更好一些）都是有记录和已知的，虽然这些漏洞很少被利用。因此对用户构成的“实际风险”仍然存在，至少现在，在理论上是很有可能的。</p><p>也就是说，没有发生<strong>已知的</strong>由于使用Mint发行版（或任何其他基于Ubuntu的未打补丁的发行版）并被通过利用Grawert引用的Ubuntu开发邮件列表上的漏洞造成身份盗窃乃至更糟的事故的情况。</p><p>但是，仅仅因为迄今为止没有人曾经钻进这扇半掩的窗户，并不能说明其他人永远不会这么做。</p><p><strong>看到Ubuntu持续被提及有关自身的（主要是理论上）隐私问题后，至少它还穿着另外一只鞋子，我们可喜的看到它对用户安全的强烈关注正在延伸至其他发行版上。</strong></p><p><em>请注意：我们已经向Linux Mint征求意见及澄清，答复将在后继文章发表。</em></p><hr>",12)),i("p",null,[n[4]||(n[4]=t("via: ",-1)),l(e,{href:"http://www.omgubuntu.co.uk/2013/11/canonical-dev-dont-use-linux-mint-online-banking-unsecure"},{default:o(()=>[...n[3]||(n[3]=[t("http://www.omgubuntu.co.uk/2013/11/canonical-dev-dont-use-linux-mint-online-banking-unsecure",-1)])]),_:1})]),i("p",null,[n[7]||(n[7]=t("译者：",-1)),l(e,{href:"https://github.com/whatever1992"},{default:o(()=>[...n[5]||(n[5]=[t("whatever1992",-1)])]),_:1}),n[8]||(n[8]=t(" 校对：",-1)),l(e,{href:"https://github.com/wxy"},{default:o(()=>[...n[6]||(n[6]=[t("wxy",-1)])]),_:1})]),i("p",null,[n[11]||(n[11]=t("本文由 ",-1)),l(e,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...n[9]||(n[9]=[t("LCTT",-1)])]),_:1}),n[12]||(n[12]=t(" 原创翻译，",-1)),l(e,{href:"http://linux.cn/"},{default:o(()=>[...n[10]||(n[10]=[t("Linux中国",-1)])]),_:1}),n[13]||(n[13]=t(" 荣誉推出",-1))])])}const T=u(d,[["render",x]]);export{f as __pageData,T as default};
